result.output:
import React from 'react';
import { ChartKitError } from '../libs';
import type { ChartKitWidget } from './widget';
export type { ChartKitHolidays } from './misc';
export type ChartKitLang = 'ru' | 'en';
export type ChartKitType = keyof ChartKitWidget;
export type ChartKitRef = {
    /**
     * Renderers may return a promise that completes when the resized chart is ready.
     * `undefined` means no completion signal is available, including while the widget is loading.
     * It does not guarantee that the chart is ready. Awaiting callers must handle rejection.
     * Gravity Charts also reports preparation failures through onError/renderError;
     * unavailable-host, zero-size and unmount cancellations only reject the promise.
     * For Gravity Charts, pass `{immediate: true}` to skip the resize debounce.
     */
    reflow: (details?: unknown) => void | Promise<void>;
};
export type ChartKitWidgetRef = {
    reflow?: ChartKitRef['reflow'];
};
export type ChartKitOnLoadData<T extends ChartKitType> = {
    widget?: ChartKitWidget[T]['widget'];
    widgetRendering?: number;
};
export type ChartKitOnRenderData = {
    renderTime?: number;
};
export type ChartKitOnChartLoad<T extends ChartKitType> = {
    widget?: ChartKitWidget[T]['widget'] | null;
};
export type ChartKitOnError = (data: {
    error: any;
}) => void;
export type ChartKitRenderPluginLoader = () => React.ReactNode;
export type ChartKitProps<T extends ChartKitType> = {
    type: T;
    data: ChartKitWidget[T]['data'];
    id?: string;
    isMobile?: boolean;
    onLoad?: (data?: ChartKitOnLoadData<T>) => void;
    /** Fires on each chartkit plugin's component render */
    onRender?: (data: ChartKitOnRenderData) => void;
    /** Fires on chartkit plugin's component mount */
    onChartLoad?: (data: ChartKitOnChartLoad<T>) => void;
    /** Fires in case of unhandled plugin's exception */
    onError?: ChartKitOnError;
    /** Used to render user's error component */
    renderError?: RenderError;
    /** Used to render user's plugin loader component */
    renderPluginLoader?: ChartKitRenderPluginLoader;
    validation?: {
        /**
         * Series count limit.
         *
         * If you have series more than limit, your chart will throw an error `'ERR.CK.TOO_MANY_LINES'`.
         *
         * - This setting applies only when provided
         * - Supported only for the `gravity-charts` plugin
         */
        seriesCountLimit?: number;
    };
} & {
    [key in keyof Omit<ChartKitWidget[T], 'data' | 'widget'>]: ChartKitWidget[T][key];
};
export type ChartKitPlugin = {
    type: ChartKitType;
    renderer: React.LazyExoticComponent<React.ComponentType<any>>;
};
export type RenderErrorOpts = {
    message: string;
    error: ChartKitError | Error;
    resetError: () => void;
};
export type RenderError = (opts: RenderErrorOpts) => React.ReactNode;
export type { ChartKitWidget };

--- chartkit component ---
import React from 'react';
import type { ChartKitProps, ChartKitRef, ChartKitType } from '../types';
import './ChartKit.css';
type ChartKitComponentProps<T extends ChartKitType> = Omit<ChartKitProps<T>, 'onError'> & {
    instanceRef?: React.ForwardedRef<ChartKitRef | undefined>;
};
declare const ChartKitComponent: <T extends ChartKitType>(props: ChartKitComponentProps<T>) => React.JSX.Element;
export declare const ChartKit: <T extends ChartKitType>(props: ChartKitProps<T> & {
    ref?: React.ForwardedRef<ChartKitRef | undefined>;
}) => ReturnType<typeof ChartKitComponent>;
export {};

--- yagr types ---
import type { MinimalValidConfig, RawSerieData, YagrConfig } from '@gravity-ui/yagr';
import type Yagr from '@gravity-ui/yagr';
import type { ChartKitProps } from '../../types';
export type { default as Yagr } from '@gravity-ui/yagr';
export type * from '@gravity-ui/yagr';
export type { YagrReactRef } from '@gravity-ui/yagr/react';
export interface CustomTooltipProps {
    yagr: Yagr<MinimalValidConfig> | undefined;
}
export type YagrWidgetProps = ChartKitProps<'yagr'> & {
    id: string;
};
export type YagrWidgetData = {
    data: {
        graphs: RawSerieData[];
        timeline: number[];
        /**
         * Allow to setup timezone for X axis and tooltip's header.
         *
         * Format example: "UTC", "Europe/Moscow".
         *
         * For more examples check [wiki](https://en.wikipedia.org/wiki/List_of_tz_database_time_zones#List)
         */
        timeZone?: string;
    };
    libraryConfig: Partial<YagrConfig>;
    sources?: Record<number, {
        data: {
            program: string;
        };
    }>;
};

--- yagr widget ---
import React from 'react';
import type { ChartKitWidgetRef } from '../../../types';
import './polyfills';
import '@gravity-ui/yagr/index.css';
import './YagrWidget.css';
declare const YagrWidget: React.ForwardRefExoticComponent<{
    type: "yagr";
    data: import("..").YagrWidgetData;
    id?: string;
    isMobile?: boolean;
    onLoad?: ((data?: import("../../..").ChartKitOnLoadData<"yagr"> | undefined) => void) | undefined;
    onRender?: (data: import("../../..").ChartKitOnRenderData) => void;
    onChartLoad?: ((data: import("../../..").ChartKitOnChartLoad<"yagr">) => void) | undefined;
    onError?: import("../../..").ChartKitOnError;
    renderError?: import("../../../types").RenderError;
    renderPluginLoader?: import("../../../types").ChartKitRenderPluginLoader;
    validation?: {
        seriesCountLimit?: number;
    };
} & {
    tooltip?: (<T extends import("..").CustomTooltipProps = import("..").CustomTooltipProps>(props: T) => React.ReactNode) | undefined;
} & {
    id: string;
} & React.RefAttributes<ChartKitWidgetRef | undefined>>;
export default YagrWidget;

