+    const spike = index % 180 > 170 ? 340 : 0;
+
+    return {
+      timestamp,
+      responseTimeMs: Math.round(92 + loadWave * 1.4 + spike + Math.sin(index / 7) * 11),
+      cpuLoad: Number((48 + loadWave + spike / 12).toFixed(1)),
+    };
+  }),
+};
