  // Indent all lines after libraryConfig until closing of the libraryConfig block
  const lines = text.split('\\n');
  const startIdx = lines.findIndex((line) => line.startsWith('          libraryConfig: {'));
  const closingIdx = lines.findIndex((line, index) => index > startIdx && line.startsWith('        }}'));
  if (startIdx "'!== -1 && closingIdx !== -1) {
    for (let index = startIdx + 1; index < closingIdx; index += 1) {
      if (lines[index].trim()) {
        lines[index] = `  ${lines[index]}`;
      }
    }
    lines[closingIdx] = '"'          },\\n        }}';
    fs.writeFileSync(path, lines.join('\\n'));
  }
}
